package com.example.deeplinksandbox

import android.app.Activity
import android.os.Bundle
import com.airbnb.deeplinkdispatch.DeepLinkHandler
// DeepLinkDelegate is generated by the annotation processor into this same package.

/**
 * Every incoming deep link lands here. The delegate matches the URI against the
 * generated registry and starts the right target Activity, then this one finishes.
 */
@DeepLinkHandler(AppDeepLinkModule::class)
class MainDeepLinkActivity : Activity() {

    override fun onCreate(savedInstanceState: Bundle?) {
        super.onCreate(savedInstanceState)
        val delegate = DeepLinkDelegate(AppDeepLinkModuleRegistry())
        delegate.dispatchFrom(this)
        finish()
    }
}
